test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source e1_source
{
	type = mysql

	sql_query = SELECT id, title, body, gid FROM e1_docs ORDER BY id
	sql_attr_uint = gid
}

index e1_plain
{
	source = e1_source
	path = /e1_plain
	index_field_lengths = 1
}

index e1_rt
{
	type = rt
	path = /e1_rt
	rt_field = title
	rt_field = body
	rt_attr_uint = gid
	index_field_lengths = 1
}

index e1_ties
{
	type = rt
	path = /e1_ties
	rt_field = body
	index_field_lengths = 1
}

queries.sphinxql:
INSERT INTO e1_rt (id,title,body,gid) VALUES
(1,'alpha alpha beta','gamma',1),
(2,'alpha','alpha alpha gamma',1),
(3,'beta gamma','alpha',2);
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_rt (id,title,body,gid) VALUES
(4,'alpha beta','beta alpha',2),
(5,'gamma','beta',3),
(6,'alpha alpha alpha','alpha beta gamma',3);
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_ties (id,body) VALUES (30,'tie'),(20,'tie'),(10,'tie');
FLUSH RAMCHUNK e1_ties;



SELECT id FROM e1_plain WHERE MATCH('alpha');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha beta');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta | gamma | missing');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta | gamma | missing') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC;
SELECT id FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC OPTION ranker=none;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY id ASC;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY WEIGHT() DESC, ID ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)');
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('@title alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('@body alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha beta') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha | beta') ORDER BY w DESC,id ASC LIMIT 2,3 OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('"alpha beta"') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') AND gid=2 ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_plain WHERE MATCH('alpha') AND gid=2 LIMIT 1; SHOW META LIKE 'total_found';
SELECT COUNT(*) FROM e1_plain WHERE MATCH('alpha') AND gid=2;


SELECT id FROM e1_rt WHERE MATCH('alpha');
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha');
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha beta');
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha | beta | gamma | missing');
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha | beta | gamma | missing') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY WEIGHT() DESC, ID ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)');
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('@title alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('@body alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha beta') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha | beta') ORDER BY w DESC,id ASC LIMIT 2,3 OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('"alpha beta"') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid=2 ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid=2 LIMIT 1,1; SHOW META LIKE 'total_found';
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid=99; SHOW META LIKE 'total_found';
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid>=1 LIMIT 2; SHOW META LIKE 'total_found';

SELECT id,weight() AS w FROM e1_ties WHERE MATCH('tie');
SELECT id,weight() AS w FROM e1_ties WHERE MATCH('tie') ORDER BY weight() DESC,id ASC OPTION ranker=bm25a;

SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid=2 LIMIT 1,1; SHOW META LIKE 'total_found';
DELETE FROM e1_rt WHERE id=3;
REPLACE INTO e1_rt (id,title,body,gid) VALUES (2,'beta','alpha alpha alpha',4);
UPDATE e1_rt SET gid=5 WHERE id=4;
FLUSH RAMCHUNK e1_rt;
OPTIMIZE TABLE e1_rt OPTION sync=1,cutoff=1;
ALTER TABLE e1_rt ADD COLUMN extra TEXT;
SELECT id,gid,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;

SELECT id,gid,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,gid,weight() AS w FROM e1_rt WHERE MATCH('alpha') AND gid=5; SHOW META LIKE 'total_found';
SELECT COUNT(*) FROM e1_rt;
